{"document": {"category": "csaf_security_advisory", "csaf_version": "2.0", "distribution": {"text": "Disclosure is not limited. (TLPv2: TLP:CLEAR)", "tlp": {"label": "WHITE"}}, "lang": "en", "notes": [{"category": "summary", "text": "The Industrial Edge App Publisher contains a vulnerability chain involving improper certificate validation and the rendering of unescaped data from backend responses. These issues can be combined to allow an attacker on the network to impersonate the management server and execute arbitrary code (RCE) on the local machine through Node.js integration.

Siemens has released an update for the Industrial Edge App Publisher and recommends to update to the latest version.", "title": "Summary"}, {"category": "general", "text": "As a general security measure, Siemens strongly recommends to protect network access to devices with appropriate mechanisms. In order to operate the devices in a protected IT environment, Siemens recommends to configure the environment according to Siemens' operational guidelines for Industrial Security (Download: https://www.siemens.com/cert/operational-guidelines-industrial-security), and to follow the recommendations in the product manuals.
Additional information on Industrial Security by Siemens can be found at: https://www.siemens.com/industrialsecurity", "title": "General Recommendations"}, {"category": "general", "text": "For further inquiries on security vulnerabilities in Siemens products and solutions, please contact the Siemens ProductCERT: https://www.siemens.com/cert/advisories", "title": "Additional Resources"}, {"category": "legal_disclaimer", "text": "The use of Siemens Security Advisories is subject to the terms and conditions listed on: https://www.siemens.com/productcert/terms-of-use.", "title": "Terms of Use"}], "publisher": {"category": "vendor", "contact_details": "productcert@siemens.com", "name": "Siemens ProductCERT", "namespace": "https://www.siemens.com"}, "references": [{"category": "self", "summary": "SSA-968435: Multiple Vulnerabilities in Industrial Edge App Publisher - HTML Version", "url": "https://cert-portal.siemens.com/productcert/html/ssa-968435.html"}, {"category": "self", "summary": "SSA-968435: Multiple Vulnerabilities in Industrial Edge App Publisher - CSAF Version", "url": "https://cert-portal.siemens.com/productcert/csaf/ssa-968435.json"}], "title": "SSA-968435: Multiple Vulnerabilities in Industrial Edge App Publisher", "tracking": {"current_release_date": "2026-10-13T00:00:00.000Z", "generator": {"engine": {"name": "Siemens ProductCERT CSAF Generator", "version": "1"}}, "id": "SSA-968435", "initial_release_date": "2026-10-13T00:00:00.000Z", "revision_history": [{"date": "2026-10-13T00:00:00.000Z", "legacy_version": "1.0", "number": "1", "summary": "Publication Date"}], "status": "interim", "version": "1"}}, "product_tree": {"branches": [{"branches": [{"branches": [{"category": "product_version_range", "name": "vers:intdot/<1.27.9", "product": {"name": "Industrial Edge App Publisher < V1.27.9", "product_id": "1"}}], "category": "product_name", "name": "Industrial Edge App Publisher"}], "category": "vendor", "name": "Siemens"}]}, "vulnerabilities": [{"cve": "CVE-2026-78556", "cwe": {"id": "CWE-295", "name": "Improper Certificate Validation"}, "notes": [{"category": "description", "text": "The affected software does not properly validate the server certificate when initiating a TLS connection. This allows an attacker to intercept and relay communication (Man-in-the-Middle attack) and to spoof a trusted entity by interfering in the communication path between the client and the intended server.", "title": "CVE Description"}], "product_status": {"known_affected": ["1"]}, "remediations": [{"category": "vendor_fix", "details": "Update to V1.27.9 or later version", "product_ids": ["1"], "url": "https://docs.eu1.edge.siemens.cloud/develop_an_application/ieap/download_the_ie_ap.html"}], "scores": [{"cvss_v3": {"baseScore": 7.4, "baseSeverity": "HIGH", "vectorString": "CVSS:3.1/AV:N/AC:H/PR:N/UI:N/S:U/C:H/I:H/A:N", "version": "3.1"}, "products": ["1"]}], "title": "CVE-2026-78556"}, {"cve": "CVE-2026-78557", "cwe": {"id": "CWE-79", "name": "Improper Neutralization of Input During Web Page Generation ('Cross-site Scripting')"}, "notes": [{"category": "description", "text": "The application fails to properly sanitize or escape data received from the backend before rendering it in the user interface. Because the front end is integrated with Node.js, this vulnerability allows for the execution of arbitrary JavaScript, which can be leveraged to achieve remote code execution (RCE) on the victim's machine", "title": "CVE Description"}], "product_status": {"known_affected": ["1"]}, "remediations": [{"category": "vendor_fix", "details": "Update to V1.27.9 or later version", "product_ids": ["1"], "url": "https://docs.eu1.edge.siemens.cloud/develop_an_application/ieap/download_the_ie_ap.html"}], "scores": [{"cvss_v3": {"baseScore": 8.3, "baseSeverity": "HIGH", "vectorString": "CVSS:3.1/AV:N/AC:H/PR:N/UI:R/S:C/C:H/I:H/A:H", "version": "3.1"}, "products": ["1"]}], "title": "CVE-2026-78557"}]}
